package kome.common.data;

import java.util.*;
import kome.common.KOMEAccessFixture;
import lotr.common.fac.LOTRFaction;
import net.minecraft.nbt.NBTTagCompound;
import org.junit.Test;
import static org.junit.Assert.*;
import static kome.common.data.KOMEKnightCommission.*;

/** Authority, replay, retained evidence and new journey, independent of cosmetic delivery. */
public class KOMEServicePromotionPass3Test {
    private static KOMEProgressionNpcRef npc(String name){return new KOMEProgressionNpcRef(UUID.randomUUID().toString(),name,"rohan",0,0,65,0);}
    private static final KOMESerfKnightDutyType[] LEGACY={KOMESerfKnightDutyType.PROVISIONING,KOMESerfKnightDutyType.PROFESSION,KOMESerfKnightDutyType.COURIER};
    private static void duties(KOMEPlayerProgression p,int count){
        for(int i=0;i<count;i++){assertTrue(KOMESerfKnightService.assignDuty(p.getSerfKnightProgression(),LEGACY[i],new NBTTagCompound(),100).success);assertTrue(KOMESerfKnightService.completeDuty(p,LEGACY[i]).success);}
    }
    private static KOMEPlayerProgression serf(KOMEWorldData data,UUID owner,KOMEProgressionNpcRef master){
        assertTrue(KOMECanonicalRankService.recognizeCommittedPledge(data,owner,"rohan"));KOMEPlayerProgression p=data.getProgression(owner);
        assertTrue(KOMESerfKnightService.setSerfdomMaster(p.getSerfKnightProgression(),master).success);return p;
    }
    private static KOMEPlayerProgression reload(KOMEPlayerProgression p){KOMEPlayerProgression loaded=new KOMEPlayerProgression();loaded.readFromNBT(p.writeToNBT());return loaded;}
    @Test public void committedPledgeGrantsSerfOnceWithoutMaster(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();assertFalse(KOMECanonicalRankService.recognizeCommittedPledge(data,owner,""));assertTrue(KOMECanonicalRankService.recognizeCommittedPledge(data,owner,"rohan"));assertFalse(KOMECanonicalRankService.recognizeCommittedPledge(data,owner,"rohan"));assertEquals(KOMEProgressionRank.SERF,data.getProgression(owner).getCanonicalRank());assertFalse(data.getProgression(owner).getSerfKnightProgression().getSerfdomMaster().isSet());}
    @Test public void genuineNativePledgeIsReadInsteadOfCallerClaim()throws Exception{try(KOMEProgressionFollowupTest.Session session=new KOMEProgressionFollowupTest.Session()){KOMEAccessFixture f=session.f;session.p.setCanonicalRank(KOMEProgressionRank.WANDERER);f.pledge(null);assertFalse(KOMECanonicalRankService.recognizePledge(f.player,false));f.pledge(LOTRFaction.ROHAN);assertTrue(KOMECanonicalRankService.recognizePledge(f.player,false));assertFalse(KOMECanonicalRankService.recognizePledge(f.player,false));assertEquals(KOMEProgressionRank.SERF,f.data.getProgression(f.player.id).getCanonicalRank());}}
    @Test public void higherRankIsPreservedWhenPledgeChanges(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();data.getProgression(owner).setCanonicalRank(KOMEProgressionRank.LORD);assertFalse(KOMECanonicalRankService.recognizeCommittedPledge(data,owner,"gondor"));assertEquals(KOMEProgressionRank.LORD,data.getProgression(owner).getCanonicalRank());}
    @Test public void masterAdmissionDoesNotChangeSerfStanding(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEPlayerProgression p=serf(data,owner,npc("Master"));assertEquals(KOMEProgressionRank.SERF,p.getCanonicalRank());assertEquals(0,KOMEServicePromotionService.duties(p.getSerfKnightProgression()));}
    @Test public void threeSameDayReportsPromoteAtCurrentMasterWithoutTrial(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEProgressionNpcRef master=npc("Master");KOMEPlayerProgression p=serf(data,owner,master);duties(p,3);assertTrue(p.getSerfKnightProgression().getTrialId().isEmpty());assertTrue(KOMEServicePromotionService.commit(data,owner,master,"rohan",150,900));assertEquals(KOMEProgressionRank.KNIGHT,p.getCanonicalRank());assertFalse(p.getSerfKnightProgression().hasLiege());assertEquals(master.entityUuid,p.getSerfKnightProgression().getFormerMaster().entityUuid);assertEquals(1,p.getServiceRecognition().records().size());assertFalse(KOMEServicePromotionService.commit(data,owner,master,"rohan",150,900));assertNotNull(p.getServiceRecognition().recommendation(owner,KOMEProgressionRank.KNIGHT,"rohan"));}
    @Test public void wrongSuperiorAndFactionCannotConfer(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEProgressionNpcRef master=npc("Master");KOMEPlayerProgression p=serf(data,owner,master);duties(p,3);assertFalse(KOMEServicePromotionService.commit(data,owner,npc("Lord"),"rohan",150,0));assertFalse(KOMEServicePromotionService.commit(data,owner,master,"gondor",150,0));assertEquals(KOMEProgressionRank.SERF,p.getCanonicalRank());}
    @Test public void lostAlignmentPreservesFinalCreditAndRetryNeedsNoFourthDuty(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEProgressionNpcRef master=npc("Master");KOMEPlayerProgression p=serf(data,owner,master);duties(p,3);assertFalse(KOMEServicePromotionService.commit(data,owner,master,"rohan",149,0));assertEquals(3,KOMEServicePromotionService.duties(reload(p).getSerfKnightProgression()));assertTrue(KOMEServicePromotionService.commit(data,owner,master,"rohan",150,0));}
    @Test public void nonFiniteAlignmentCannotPromote(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEProgressionNpcRef master=npc("Master");KOMEPlayerProgression p=serf(data,owner,master);duties(p,3);assertFalse(KOMEServicePromotionService.commit(data,owner,master,"rohan",Double.NaN,0));}
    @Test public void incompleteAndDuplicateReportsCannotEarnExtraCredit(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEProgressionNpcRef master=npc("Master");KOMEPlayerProgression p=serf(data,owner,master);duties(p,2);assertTrue(KOMESerfKnightService.completeDuty(p,LEGACY[0]).success);assertEquals(2,KOMEServicePromotionService.duties(p.getSerfKnightProgression()));assertFalse(KOMEServicePromotionService.commit(data,owner,master,"rohan",150,0));}
    @Test public void staffForcedAndHistoricalFlagsAreNotEarnedService(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEProgressionNpcRef master=npc("Master");KOMEPlayerProgression p=serf(data,owner,master);duties(p,3);for(KOMESerfKnightDutyType t:LEGACY)p.getSerfKnightProgression().getDuty(t).adminForced=true;p.grant("serf.title_knight");assertFalse(KOMEServicePromotionService.commit(data,owner,master,"rohan",10000,0));}
    @Test public void expandedPoolCanUseThreeDistinctExperiences(){assertEquals(6,KOMESerfKnightDutyType.values().length);KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEPlayerProgression p=serf(data,owner,npc("Master"));for(KOMESerfKnightDutyType t:new KOMESerfKnightDutyType[]{KOMESerfKnightDutyType.PROVISIONING,KOMESerfKnightDutyType.ESCORT,KOMESerfKnightDutyType.RECOVERY}){assertTrue(KOMESerfKnightService.assignDuty(p.getSerfKnightProgression(),t,null,100).success);assertTrue(KOMESerfKnightService.completeDuty(p,t).success);}assertTrue(KOMESerfKnightService.allDutiesComplete(p.getSerfKnightProgression()));assertFalse(KOMESerfKnightService.assignDuty(p.getSerfKnightProgression(),KOMESerfKnightDutyType.DEFENSE,null,100).success);}
    private static KOMEPlayerProgression knight(KOMEWorldData data,UUID owner,KOMEProgressionNpcRef lord,int credits){KOMEPlayerProgression p=data.getProgression(owner);p.setCanonicalRank(KOMEProgressionRank.KNIGHT);p.getSerfKnightProgression().setLiege(lord);for(int i=0;i<credits;i++){KOMEKnightCommission a=new KOMEKnightCommission(Type.values()[i],lord);a.stage=Stage.READY_TO_REPORT;assertTrue(p.getKnightService().offer(a));assertTrue(p.getKnightService().report(lord));}return p;}
    @Test public void currentLordConfersLordAfterThreeReportsWithoutPrince(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEProgressionNpcRef lord=npc("Lord");KOMEPlayerProgression p=knight(data,owner,lord,3);assertTrue(KOMEServicePromotionService.commit(data,owner,lord,"rohan",2000,1));assertEquals(KOMEProgressionRank.LORD,p.getCanonicalRank());assertFalse(p.getSerfKnightProgression().hasLiege());assertNull(p.getLordship().assignment());assertNotNull(p.getServiceRecognition().recommendation(owner,KOMEProgressionRank.LORD,"rohan"));}
    @Test public void knightAlignmentDropPreservesReports(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEProgressionNpcRef lord=npc("Lord");KOMEPlayerProgression p=knight(data,owner,lord,3);assertFalse(KOMEServicePromotionService.commit(data,owner,lord,"rohan",1999,1));assertEquals(3,reload(p).getKnightService().qualifyingTypes("rohan").size());assertTrue(KOMEServicePromotionService.commit(data,owner,lord,"rohan",2000,1));}
    @Test public void forgedLetterOrWrongRecipientDoesNotCreateAuthority(){KOMEPlayerProgression p=new KOMEPlayerProgression();p.setCanonicalRank(KOMEProgressionRank.KNIGHT);assertFalse(KOMERecommendationService.eligible(p,UUID.randomUUID(),"rohan"));UUID owner=UUID.randomUUID();p.getServiceRecognition().earn(owner,npc("Master"),KOMEProgressionRank.SERF,KOMEProgressionRank.KNIGHT,"Reported service",0);assertFalse(KOMERecommendationService.eligible(p,UUID.randomUUID(),"rohan"));assertFalse(KOMERecommendationService.eligible(p,owner,"gondor"));p.setCanonicalRank(KOMEProgressionRank.LORD);assertFalse(KOMERecommendationService.eligible(p,owner,"rohan"));}
    @Test public void recommendationRedeemsOnceAndKeepsHistoryOnRestart(){UUID owner=UUID.randomUUID();KOMEPlayerProgression p=new KOMEPlayerProgression();p.setCanonicalRank(KOMEProgressionRank.KNIGHT);KOMEServiceRecognition.Record r=p.getServiceRecognition().earn(owner,npc("Master"),KOMEProgressionRank.SERF,KOMEProgressionRank.KNIGHT,"Three reported duties",0);KOMEProgressionNpcRef lord=npc("Lord");assertTrue(KOMERecommendationService.redeem(p,owner,"rohan",lord));assertFalse(KOMERecommendationService.redeem(p,owner,"rohan",npc("Second Lord")));KOMEPlayerProgression loaded=reload(p);assertTrue(loaded.getServiceRecognition().records().get(0).redeemed);assertEquals(r.id,loaded.getServiceRecognition().records().get(0).id);assertEquals(lord.entityUuid,loaded.getSerfKnightProgression().getLiege().entityUuid);}
    @Test public void factionSwitchPermanentlyInvalidatesLetterButKeepsMentorship(){UUID owner=UUID.randomUUID();KOMEPlayerProgression p=new KOMEPlayerProgression();p.setCanonicalRank(KOMEProgressionRank.KNIGHT);p.getServiceRecognition().earn(owner,npc("Master"),KOMEProgressionRank.SERF,KOMEProgressionRank.KNIGHT,"Service",0);p.getServiceRecognition().allegianceChanged("gondor");p.getServiceRecognition().allegianceChanged("rohan");assertFalse(KOMERecommendationService.eligible(reload(p),owner,"rohan"));assertEquals(1,p.getServiceRecognition().records().size());assertEquals(KOMEProgressionRank.KNIGHT,p.getCanonicalRank());}
    @Test public void rankCorrectionCannotReuseAlreadyRecognizedService(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEProgressionNpcRef master=npc("Master");KOMEPlayerProgression p=serf(data,owner,master);duties(p,3);assertTrue(KOMEServicePromotionService.commit(data,owner,master,"rohan",150,0));p.setCanonicalRank(KOMEProgressionRank.SERF);p.getSerfKnightProgression().setSerfdomMaster(master);assertFalse(KOMEServicePromotionService.commit(data,owner,master,"rohan",150,0));assertEquals(1,p.getServiceRecognition().records().size());}
    @Test public void serviceObjectiveSavedIdentitySurvivesReload(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEProgressionNpcRef master=npc("Master");KOMEPlayerProgression p=serf(data,owner,master);KOMESerfKnightTrialAssignment a=KOMESerfKnightTrialAssignment.create(KOMESerfKnightTrial.forId("recovery"),master,100,0);a.data.setBoolean("OrdinaryDuty",true);p.getSerfKnightProgression().setTrial(a);p.getSerfKnightProgression().assignDuty(KOMESerfKnightDutyType.RECOVERY,a.writeToNBT());KOMEPlayerProgression loaded=reload(p);assertTrue(loaded.getSerfKnightProgression().ordinaryObjective());assertEquals(a.assignmentToken,loaded.getSerfKnightProgression().getTrialAssignment().assignmentToken);assertFalse(loaded.getSerfKnightProgression().hasLiege());}
    @Test public void guiUsesThreeServiceCreditsAndNoMandatoryTrials(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEPlayerProgression p=serf(data,owner,npc("Master"));duties(p,2);KOMEProgressionRankSummary s=KOMEProgressionRankSummary.project(p,150,"rohan");assertEquals(2,s.requirements.size());assertEquals(3,s.requirements.get(0).required);assertFalse(s.activityObjective.contains("Trial"));p.setCanonicalRank(KOMEProgressionRank.KNIGHT);s=KOMEProgressionRankSummary.project(p,2000,"rohan");assertEquals(2,s.requirements.size());assertFalse(s.activityObjective.contains("Prince"));}
    @Test public void oldTrialEvidenceRetiresWithoutRankRewardOrLostCredits()throws Exception{KOMEAccessFixture f=new KOMEAccessFixture();f.pledge(LOTRFaction.ROHAN);KOMEPlayerProgression p=serf(f.data,f.player.id,npc("Master"));duties(p,3);KOMEProgressionNpcRef oldLord=npc("Old Lord");assertTrue(KOMESerfKnightService.acceptStandingTrial(p.getSerfKnightProgression(),oldLord,KOMEProgressionNpcRank.LORD,true,new Random(1),100,f.player.id).success);assertTrue(KOMEServicePromotionService.migrate(f.player));assertFalse(KOMEServicePromotionService.migrate(f.player));assertEquals(KOMEProgressionRank.SERF,p.getCanonicalRank());assertEquals(3,KOMEServicePromotionService.duties(p.getSerfKnightProgression()));assertNull(p.getSerfKnightProgression().getTrialAssignment());assertFalse(p.getSerfKnightProgression().hasLiege());assertTrue(p.getServiceRecognition().write().hasKey("RetiredStanding",10));assertTrue(p.getSerfKnightProgression().hasMasterRelationship());}
    @Test public void nativeInvasionOnlyCountsRealVictoryOnce(){KOMEWorldData data=new KOMEWorldData("service");UUID owner=UUID.randomUUID();KOMEProgressionNpcRef lord=npc("Lord");KOMEPlayerProgression p=knight(data,owner,lord,0);KOMEKnightCommission a=new KOMEKnightCommission(Type.BORDER_INCURSION,lord);a.stage=Stage.READY_TO_REPORT;a.participated=true;KOMELordshipTrial t=new KOMELordshipTrial(KOMELordshipTrial.Scenario.NATIVE_INVASION,a,Arrays.asList("Guard","Guard","Guard","Guard"));t.ordinaryService=true;t.nativeInvasion=true;assertFalse(p.getKnightService().reportInvasion(t,lord));t.nativeVictory=true;assertTrue(p.getKnightService().reportInvasion(t,lord));assertFalse(p.getKnightService().reportInvasion(t,lord));assertTrue(reload(p).getKnightService().qualifyingTypes("rohan").contains(Type.NATIVE_INVASION));}
}
